-- Ecuador deep-dive ES/DE/FR translations (completing 381).
-- INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'CTC de tipo clearance mediante claves de autorización autocalculadas, con validación del SRI casi instantánea', 'Esta página de análisis refleja las resoluciones públicas del SRI y la información del sector disponible a principios de agosto de 2026, y se ofrece a título informativo general, no como asesoramiento legal o fiscal. Confirme los requisitos vigentes directamente con el SRI o con un asesor fiscal ecuatoriano antes de basar en esta página sus decisiones de cumplimiento.', 'El SRI de Ecuador exige la validación de facturas electrónicas casi en tiempo real desde 2014, alcanzando una cobertura prácticamente universal a finales de 2022. El cambio destacado de enero de 2026 no fue la introducción del reporte en tiempo real -- cerró una flexibilización temporal concedida durante la emergencia eléctrica del país en 2024, volviendo a la regla vigente de transmisión inmediata.', 'Las facturas se emiten en XML conforme a los esquemas XSD publicados por el SRI. El emisor autocalcula una clave de acceso de 49 dígitos compuesta por la fecha, el tipo de documento, el RUC, el ambiente, el establecimiento, el punto de emisión, el número secuencial, un componente aleatorio, el tipo de emisión y un dígito verificador, y luego aplica una Firma Electrónica Avanzada obligatoria (XAdES-BES) antes de enviarla al SRI. Se requiere una representación impresa (RIDE), con código de barras GS1-128, siempre que el receptor no pueda o no quiera aceptar el XML directamente.', 'El mandato de facturación electrónica de Ecuador es prácticamente universal para los contribuyentes registrados a efectos de IVA, tras un despliegue escalonado que alcanzó ~100% de cobertura a finales de 2022 -- pero queda una excepción real: los contribuyentes RIMPE ''Negocios Populares'' (ingresos de hasta 20.000 USD) están exentos y pueden seguir utilizando ''notas de venta RISE'' en papel. Solo están realmente obligados a emitir facturas electrónicas los RIMPE ''Emprendedores'' (hasta 300.000 USD) y los contribuyentes de mayor tamaño, así que no asuma que toda contraparte ecuatoriana está dentro del alcance.', 'Dado que el cambio de la ventana de transmisión de enero de 2026 es reciente, la mayoría de las empresas tienen trabajo real de implementación por delante: confirmar que sus sistemas vuelven a transmitir de forma inmediata en lugar de depender de la ya eliminada ventana de emergencia, y que sus flujos de anulación reflejan el plazo acortado.', 'Ecuador respalda sus normas de facturación electrónica con un régimen de sanciones real y documentado, denominado en Remuneración Básica Unificada (RBU) -- el salario básico unificado de Ecuador, confirmado en 482 USD para 2026 -- que escala de forma pronunciada según la categoría del contribuyente, desde los grandes contribuyentes hasta las personas no inscritas.', 'El SRI de Ecuador exige la transmisión de facturas electrónicas casi en tiempo real desde 2014, alcanzando una cobertura prácticamente universal entre los contribuyentes de IVA a finales de 2022 (con la excepción de RIMPE Negocios Populares). Un período de gracia temporal de 4 días hábiles concedido durante la crisis de emergencia eléctrica de 2024 se cerró el 1 de enero de 2026, restableciendo la regla vigente de transmisión inmediata. El modelo se describe mejor como de tipo clearance: los emisores autocalculan una clave de autorización de 49 dígitos, y la validación automatizada del SRI -- que normalmente se completa en segundos -- es necesaria para la validez legal.', '🇪🇨' FROM countries WHERE name_en = 'Ecuador';

