INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato, claves y validación', '[["Formato", "XML, conforme a los esquemas XSD publicados por el SRI"], ["Clave de autorización", "Clave de acceso autocalculada de 49 dígitos: fecha, tipo de documento, RUC, ambiente, establecimiento, punto de emisión, número secuencial, componente aleatorio, tipo de emisión y dígito verificador"], ["Firma digital", "Firma Electrónica Avanzada obligatoria (XAdES-BES)"], ["Validación del SRI", "Automatizada; normalmente se completa en segundos y es necesaria para la validez legal"]]', 'Algunas fuentes de proveedores describen una secuencia más estricta en la que el SRI aprueba primero y luego se entrega; otras describen una entrega inmediata con autorización en paralelo, en la que la factura se vuelve ''definitivo'' una vez que el SRI la autoriza. Se trata de una ambigüedad genuina y no resuelta en las fuentes secundarias -- en la práctica, la mayoría de las implementaciones tratan esto como una secuencia de clearance, ya que la validación del SRI suele ser casi instantánea y se requiere antes de que una factura sea legalmente válida.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'RIDE, conservación y entrega', '[["RIDE", "Representación Impresa de Documento Electrónico -- una representación impresa con código de barras GS1-128, requerida cuando el receptor no puede o no quiere aceptar el XML directamente"], ["Entrega", "El XML se entrega directamente al comprador, o el RIDE cuando se requiere una copia impresa/visual"], ["Conservación", "Mínimo 7 años, tanto para el emisor como para el receptor"], ["Organismo responsable", "Servicio de Rentas Internas (SRI)"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Familia de documentos', '[["Facturas", "Facturas estándar"], ["Comprobantes de retención", "Comprobantes de retención de impuestos"], ["Guías de remisión", "Documentación para bienes en tránsito"], ["Notas de crédito / débito", "Notas de crédito y notas de débito"], ["Liquidaciones de compra", "Liquidaciones de compra"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de clearance autocalculado', 'Una factura electrónica ecuatoriana recorre esta secuencia -- el emisor realiza el cálculo inicial, pero es la autorización del SRI la que hace válido al documento:', 'La validación automatizada del SRI normalmente se completa en segundos -- trate la autorización como un paso necesario y casi inmediato de la emisión, no como una formalidad en segundo plano.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador';
