INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El emisor aplica la Firma Electrónica Avanzada obligatoria (XAdES-BES)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El XML firmado se envía al SRI para su validación automatizada' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'El SRI autoriza el documento -- normalmente en segundos -- y asigna el número de autorización' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'es', 'La factura autorizada se entrega al comprador, en XML o como RIDE cuando se requiere una copia impresa' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién está realmente dentro del alcance', '[["Contribuyentes generales registrados a efectos de IVA", "Dentro del alcance, tras el despliegue escalonado de 2014-2022 que alcanzó una universalidad efectiva"], ["RIMPE Emprendedores", "Dentro del alcance (ingresos de hasta 300.000 USD)"], ["RIMPE Negocios Populares", "EXENTOS -- ingresos de hasta 20.000 USD; pueden seguir utilizando notas de venta RISE en papel"], ["Proveedores extranjeros/no residentes", "Entran en el alcance al registrarse a efectos fiscales en Ecuador"]]', 'Prácticamente universal fuera de la excepción de Negocios Populares -- no asuma que literalmente toda contraparte ecuatoriana está en facturación electrónica.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Historial de la ventana de transmisión', '[["2014-2018", "Inmediata, en el momento de la transacción"], ["2018-2024", "Inmediata, o hasta 72 horas para emisores de alto volumen"], ["Nov 2024-Dic 2025", "Inmediata, o hasta 4 días hábiles -- alivio temporal por la emergencia eléctrica"], ["Desde el 1 ene 2026", "Inmediata de nuevo -- se eliminó la ventana de 4 días hábiles"]]', 'El cambio de enero de 2026 cierra una flexibilización temporal concedida durante la emergencia eléctrica de Ecuador en 2024 -- restablece, en lugar de introducir, un requisito de transmisión casi en tiempo real vigente desde 2014.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 Las sanciones se fijan en RBU y escalan de forma pronunciada según la categoría del contribuyente', NULL, NULL, 'La Resolución del SRI NAC-DGERCGC24-00000022 (6 de junio de 2024) fija las sanciones en Remuneración Básica Unificada (RBU) -- el salario básico unificado de Ecuador, confirmado en 482 USD para 2026 -- con cifras distintas y más altas por no transmitir una factura que por no entregarla, y una escala que aumenta marcadamente por categoría, desde los grandes contribuyentes hasta las personas no inscritas. Vea la tabla de sanciones más abajo para cifras representativas.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔒 Las facturas a consumidor final ya no se pueden anular', NULL, NULL, 'A partir del 1 de enero de 2026, las facturas emitidas a ''consumidor final'' ya no pueden anularse, junto con un plazo de anulación acortado -- trasladado del día 10 al día 7 del mes siguiente por la Resolución NAC-DGERCGC25-00000017. Las empresas que solían anular o corregir facturas a consumidor final después de emitidas necesitan ahora un proceso distinto.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ La excepción de Negocios Populares no significa riesgo cero', NULL, NULL, 'Incluso la categoría más pequeña de contribuyentes de Ecuador no está libre de sanciones: RIMPE Negocios Populares sigue enfrentando una multa de 1 RBU (unos 482 USD) por incumplimientos de entrega o de transmisión, a pesar de estar exenta del propio mandato de facturación electrónica y de poder utilizar notas de venta RISE en papel.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

