INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme qué categoría de contribuyente le aplica a su empresa', 'Tanto el alcance como la exposición a sanciones dependen de si es un gran contribuyente, un contribuyente especial, una sociedad general, o si está bajo RIMPE Emprendedores o Negocios Populares -- confirme su categoría con el SRI o con un asesor local antes de basarse en una cifra genérica.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su software de facturación genera correctamente la clave de acceso de 49 dígitos y aplica la firma XAdES-BES', 'Una clave de acceso mal formada o la ausencia de la Firma Electrónica Avanzada hará que el SRI rechace la factura de plano -- verifique ambos aspectos antes de poner en marcha cualquier sistema nuevo.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Incorpore una comprobación de autorización del SRI en tiempo real en su proceso de emisión', 'No trate una clave de acceso autocalculada por sí sola como una factura válida -- la autorización del SRI, que normalmente se recibe en segundos, es lo que realmente hace legalmente válido al documento.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Actualice sus sistemas a la transmisión inmediata', 'La ventana de emergencia de 4 días hábiles concedida en noviembre de 2024 ya no se aplica desde el 1 de enero de 2026 -- confirme que su flujo de facturación transmite al SRI de inmediato, y no según el calendario diferido ya eliminado.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Ajuste los flujos de anulación de facturas para los documentos a consumidor final', 'Las facturas a consumidor final dejaron de poder anularse desde el 1 de enero de 2026, y el plazo general de anulación se trasladó del día 10 al día 7 del mes siguiente -- actualice sus procesos en consecuencia.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Conserve las copias en XML y RIDE durante al menos 7 años', 'Tanto el emisor como el receptor deben conservar los documentos electrónicos durante un mínimo de 7 años -- incorpore esto a su política de gestión documental tanto para facturas emitidas como recibidas.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'SRI — Facturación Electrónica (centro de facturación electrónica)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Ecuador' AND pt.sort_order = 0;
