-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freigabemodell (Clearance-CTC) mit selbst berechneten Autorisierungsschlüsseln und nahezu sofortiger SRI-Validierung', 'Diese Analyseseite spiegelt öffentlich verfügbare SRI-Entschließungen und Brancheninformationen mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt beim SRI oder einem ecuadorianischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Ecuadors SRI verlangt seit 2014 eine Echtzeit-nahe Validierung elektronischer Rechnungen und erreichte bis Ende 2022 eine praktisch flächendeckende Abdeckung. Die zentrale Änderung im Januar 2026 war nicht die Einführung einer Echtzeit-Meldepflicht -- sie beendete eine vorübergehende Lockerung, die während des Stromnotstands des Landes 2024 gewährt worden war, und stellte die geltende Regel der sofortigen Übermittlung wieder her.', 'Rechnungen werden im XML-Format gemäß den von SRI veröffentlichten XSD-Schemata ausgestellt. Der Aussteller berechnet selbst einen 49-stelligen Zugangscode (clave de acceso), der sich aus Datum, Dokumenttyp, RUC, Umgebung, Niederlassung, Ausstellungspunkt, laufender Nummer, einer Zufallskomponente, Ausstellungsart und einer Prüfziffer zusammensetzt, und wendet dann vor der Übermittlung an das SRI eine verpflichtende Advanced Electronic Signature (Firma Electrónica Avanzada / XAdES-BES) an. Eine gedruckte Darstellung (RIDE) mit GS1-128-Barcode ist erforderlich, wann immer der Empfänger das XML nicht direkt akzeptieren kann oder will.', 'Ecuadors E-Rechnungspflicht ist für umsatzsteuerlich registrierte Steuerpflichtige praktisch flächendeckend, nach einer stufenweisen Einführung, die bis Ende 2022 eine Abdeckung von ~100 % erreichte -- doch eine echte Ausnahme bleibt bestehen: RIMPE-Steuerpflichtige der Kategorie „Negocios Populares" (Einkommen bis 20.000 USD) sind befreit und dürfen weiterhin Papier-„notas de venta RISE" verwenden. Nur RIMPE „Emprendedores" (bis 300.000 USD) und größere Steuerpflichtige sind tatsächlich zur elektronischen Rechnungsstellung verpflichtet -- gehen Sie also nicht davon aus, dass jede ecuadorianische Gegenpartei in den Anwendungsbereich fällt.', 'Da die Änderung des Übermittlungsfensters im Januar 2026 aktuell ist, liegt vor den meisten Unternehmen noch echte Umsetzungsarbeit -- die Bestätigung, dass ihre Systeme wieder sofort übermitteln, statt sich auf das inzwischen gestrichene Notstandsfenster zu verlassen, und dass ihre Stornierungsabläufe die verkürzte Frist widerspiegeln.', 'Ecuador untermauert seine E-Rechnungsvorschriften mit einem realen, belegten Sanktionsschema, das in Remuneración Básica Unificada (RBU) angegeben ist -- Ecuadors Grundlohn, für 2026 mit 482 USD bestätigt --, das je nach Steuerpflichtigenkategorie stark ansteigt, von Großsteuerpflichtigen bis hin zu nicht registrierten Personen.', 'Ecuadors SRI verlangt seit 2014 die Echtzeit-nahe Übermittlung elektronischer Rechnungen und erreichte bis Ende 2022 eine praktisch flächendeckende Abdeckung unter den umsatzsteuerpflichtigen Steuerpflichtigen (mit Ausnahme von RIMPE Negocios Populares). Eine vorübergehende Karenzfrist von 4 Werktagen, die während der Stromnotstandskrise 2024 gewährt wurde, wurde am 1. Januar 2026 beendet und stellte die geltende Regel der sofortigen Übermittlung wieder her. Das Modell lässt sich am besten als Freigabemodell (Clearance) beschreiben: Aussteller berechnen selbst einen 49-stelligen Autorisierungsschlüssel, und die automatisierte Validierung des SRI -- die typischerweise innerhalb von Sekunden abgeschlossen ist -- ist für die Rechtsgültigkeit erforderlich.', '🇪🇨' FROM countries WHERE name_en = 'Ecuador';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Seit 2014', 'Echtzeit-nahe E-Rechnung wird verlangt' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Ecuador' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Nov. 2022', '~100% Abdeckung erreicht -- 1.212.712 Steuerpflichtige freigegeben' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Ecuador' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2026', 'Sofortige Übermittlung wieder verpflichtend' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Ecuador' AND s.sort_order = 2;
