INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format, Schlüssel & Validierung', '[["Format", "XML, gemäß den von SRI veröffentlichten XSD-Schemata"], ["Autorisierungsschlüssel", "Selbst berechneter 49-stelliger Zugangscode (clave de acceso): Datum, Dokumenttyp, RUC, Umgebung, Niederlassung, Ausstellungspunkt, laufende Nummer, Zufallskomponente, Ausstellungsart und eine Prüfziffer"], ["Digitale Signatur", "Verpflichtende Advanced Electronic Signature (Firma Electrónica Avanzada / XAdES-BES)"], ["SRI-Validierung", "Automatisiert; wird typischerweise innerhalb von Sekunden abgeschlossen und ist für die Rechtsgültigkeit erforderlich"]]', 'Manche Anbieterquellen beschreiben eine strengere Abfolge, bei der das SRI zuerst genehmigt und dann geliefert wird; andere beschreiben eine sofortige Lieferung mit paralleler Autorisierung, bei der die Rechnung erst nach Autorisierung durch das SRI „definitivo" wird. Dies ist eine echte, ungeklärte Uneindeutigkeit in Sekundärquellen -- in der Praxis wird dies meist als Freigabeabfolge behandelt, da die Validierung des SRI normalerweise nahezu sofort erfolgt und vor der Rechtsgültigkeit einer Rechnung erforderlich ist.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'RIDE, Aufbewahrung & Zustellung', '[["RIDE", "Representación Impresa de Documento Electrónico -- eine gedruckte Darstellung mit GS1-128-Barcode, erforderlich, wenn der Empfänger das XML nicht direkt akzeptieren kann oder will"], ["Zustellung", "XML wird direkt an den Käufer geliefert, oder RIDE, wenn eine gedruckte/visuelle Kopie erforderlich ist"], ["Aufbewahrung", "Mindestens 7 Jahre, sowohl für Aussteller als auch Empfänger"], ["Zuständige Behörde", "Servicio de Rentas Internas (SRI)"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Dokumentenfamilie', '[["Facturas", "Standardrechnungen"], ["Comprobantes de retención", "Quellensteuer-/Einbehaltungsbelege"], ["Guías de remisión", "Versandbegleitdokumente für Waren im Transit"], ["Notas de crédito / débito", "Gutschriften und Lastschriften"], ["Liquidaciones de compra", "Kaufabrechnungen"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der selbst berechnete Freigabeablauf', 'Eine ecuadorianische E-Rechnung durchläuft diese Abfolge -- der Aussteller führt die anfängliche Berechnung durch, doch erst die Autorisierung des SRI macht das Dokument gültig:', 'Die automatisierte Validierung des SRI wird normalerweise innerhalb von Sekunden abgeschlossen -- behandeln Sie die Autorisierung als erforderlichen, nahezu sofortigen Schritt der Ausstellung, nicht als Formalität im Hintergrund.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Aussteller erstellt die XML-Rechnung und berechnet selbst den 49-stelligen Zugangscode (clave de acceso)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Der Aussteller wendet die verpflichtende Advanced Electronic Signature (XAdES-BES) an' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das signierte XML wird zur automatisierten Validierung an das SRI übermittelt' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Das SRI autorisiert das Dokument -- typischerweise innerhalb von Sekunden -- und vergibt die número de autorización' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'de', 'Die autorisierte Rechnung wird an den Käufer geliefert, als XML oder als RIDE, wenn eine gedruckte Kopie erforderlich ist' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer tatsächlich in den Anwendungsbereich fällt', '[["Allgemeine umsatzsteuerlich registrierte Steuerpflichtige", "Im Anwendungsbereich, nach der stufenweisen Einführung 2014-2022, die eine faktische Flächendeckung erreichte"], ["RIMPE Emprendedores", "Im Anwendungsbereich (Einkommen bis 300.000 USD)"], ["RIMPE Negocios Populares", "BEFREIT -- Einkommen bis 20.000 USD; dürfen weiterhin Papier-notas de venta RISE verwenden"], ["Ausländische/gebietsfremde Lieferanten", "Fallen bei Registrierung für ecuadorianische Steuerzwecke in den Anwendungsbereich"]]', 'Praktisch flächendeckend außerhalb der Negocios-Populares-Ausnahme -- gehen Sie nicht davon aus, dass buchstäblich jede ecuadorianische Gegenpartei elektronisch abrechnet.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Historie des Übermittlungsfensters', '[["2014-2018", "Sofort, im Moment der Transaktion"], ["2018-2024", "Sofort, oder bis zu 72 Stunden für Aussteller mit hohem Volumen"], ["Nov. 2024-Dez. 2025", "Sofort, oder bis zu 4 Werktage -- vorübergehende Entlastung wegen des Stromnotstands"], ["Ab 1. Jan. 2026", "Wieder sofort -- die 4-Werktage-Frist wurde gestrichen"]]', 'Die Änderung vom Januar 2026 beendet eine vorübergehende Lockerung, die während Ecuadors Stromnotstand 2024 gewährt wurde -- sie stellt eine seit 2014 geltende Echtzeit-nahe Übermittlungspflicht wieder her, statt sie neu einzuführen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 Strafen werden in RBU festgelegt und steigen je nach Steuerpflichtigenkategorie stark an', NULL, NULL, 'Die SRI-Entschließung NAC-DGERCGC24-00000022 (6. Juni 2024) legt Strafen in Remuneración Básica Unificada (RBU) fest -- Ecuadors Grundlohn, für 2026 mit 482 USD bestätigt -- mit separaten, höheren Beträgen für die Nichtübermittlung einer Rechnung als für deren Nichtzustellung, und einem Schema, das je nach Kategorie stark ansteigt, von Großsteuerpflichtigen bis hin zu nicht registrierten Personen. Siehe die Strafentabelle unten für repräsentative Zahlen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔒 Rechnungen an consumidor final sind jetzt nicht mehr stornierbar', NULL, NULL, 'Ab dem 1. Januar 2026 können an „consumidor final" ausgestellte Rechnungen nicht mehr storniert werden, zusammen mit einer verkürzten Stornierungsfrist -- durch die Entschließung NAC-DGERCGC25-00000017 vom 10. auf den 7. des Folgemonats verschoben. Unternehmen, die routinemäßig Endverbraucherrechnungen im Nachhinein stornierten oder korrigierten, benötigen jetzt einen anderen Prozess.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Die Negocios-Populares-Ausnahme bedeutet kein Nullrisiko', NULL, NULL, 'Selbst Ecuadors kleinste Steuerpflichtigenkategorie ist nicht sanktionsfrei: RIMPE Negocios Populares droht weiterhin eine Strafe von 1 RBU (rund 482 USD) für Verstöße gegen die Zustellung oder Übermittlung, obwohl diese Kategorie von der E-Rechnungspflicht selbst befreit ist und Papier-notas de venta RISE verwenden darf.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

