INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Zur Buchführung verpflichtete Gesellschaften -- Nichtzustellung / Nichtübermittlung', '3.374 USD / 4.820 USD (7 RBU / 10 RBU)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Ecuador' AND pr.sort_order = 2;
