INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, welche Steuerpflichtigenkategorie für Ihr Unternehmen gilt', 'Sowohl der Anwendungsbereich als auch das Strafrisiko hängen davon ab, ob Sie ein Großsteuerpflichtiger, ein besonderer Steuerpflichtiger, eine allgemeine Gesellschaft sind, oder unter RIMPE Emprendedores oder Negocios Populares fallen -- bestätigen Sie Ihre Kategorie beim SRI oder einem lokalen Berater, bevor Sie sich auf eine allgemeine Zahl verlassen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Ihre Rechnungssoftware den 49-stelligen Zugangscode korrekt erstellt und die XAdES-BES-Signatur anwendet', 'Ein fehlerhaft gebildeter Zugangscode oder eine fehlende Advanced Electronic Signature führt dazu, dass das SRI die Rechnung rundweg ablehnt -- prüfen Sie beides, bevor Sie ein neues System live schalten.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Integrieren Sie eine Echtzeit-Autorisierungsprüfung des SRI in Ihren Ausstellungsprozess', 'Behandeln Sie einen selbst berechneten Zugangscode allein nicht als gültige Rechnung -- erst die Autorisierung durch das SRI, die normalerweise innerhalb von Sekunden eintrifft, macht das Dokument rechtsgültig.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Stellen Sie Ihre Systeme auf sofortige Übermittlung um', 'Das im November 2024 gewährte 4-Werktage-Notstandsfenster gilt seit dem 1. Januar 2026 nicht mehr -- prüfen Sie, ob Ihre Rechnungspipeline sofort an das SRI übermittelt und nicht mehr nach dem inzwischen gestrichenen verzögerten Zeitplan arbeitet.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Passen Sie die Stornierungsabläufe für consumidor-final-Dokumente an', 'Rechnungen an consumidor final wurden ab dem 1. Januar 2026 nicht mehr stornierbar, und die allgemeine Stornierungsfrist verschob sich vom 10. auf den 7. des Folgemonats -- passen Sie Ihre Prozesse entsprechend an.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bewahren Sie XML- und RIDE-Kopien mindestens 7 Jahre lang auf', 'Sowohl Aussteller als auch Empfänger müssen elektronische Dokumente mindestens 7 Jahre lang aufbewahren -- integrieren Sie dies in Ihre Dokumentenverwaltungsrichtlinie für ausgestellte wie empfangene Rechnungen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'SRI — Facturación Electrónica (Zentrum für elektronische Rechnungsstellung)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Ecuador' AND pt.sort_order = 0;
