-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'CTC de type dédouanement via des clés d''autorisation auto-calculées, avec une validation du SRI quasi instantanée', 'Cette page d''analyse reflète les résolutions publiques du SRI et les informations sectorielles disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès du SRI ou d''un conseiller fiscal équatorien avant de fonder vos décisions de conformité sur cette page.', 'Le SRI équatorien exige la validation des factures électroniques quasi en temps réel depuis 2014, atteignant une couverture pratiquement universelle fin 2022. Le changement phare de janvier 2026 n''était pas l''introduction d''une déclaration en temps réel -- il a mis fin à un assouplissement temporaire accordé pendant l''urgence électrique du pays en 2024, revenant à la règle en vigueur de transmission immédiate.', 'Les factures sont émises au format XML conformément aux schémas XSD publiés par le SRI. L''émetteur calcule lui-même une clé d''accès de 49 chiffres composée de la date, du type de document, du RUC, de l''environnement, de l''établissement, du point d''émission, du numéro séquentiel, d''une composante aléatoire, du type d''émission et d''un chiffre de contrôle, puis applique une signature électronique avancée obligatoire (Firma Electrónica Avanzada / XAdES-BES) avant de la soumettre au SRI. Une représentation imprimée (RIDE), portant un code-barres GS1-128, est requise chaque fois que le destinataire ne peut pas ou ne veut pas accepter le XML directement.', 'L''obligation de facturation électronique de l''Équateur est pratiquement universelle pour les contribuables assujettis à la TVA, après un déploiement progressif ayant atteint une couverture d''environ 100 % fin 2022 -- mais une véritable exception subsiste : les contribuables RIMPE « Negocios Populares » (revenus jusqu''à 20 000 USD) sont exemptés et peuvent continuer à utiliser des « notas de venta RISE » papier. Seuls les RIMPE « Emprendedores » (jusqu''à 300 000 USD) et les contribuables plus importants sont réellement tenus d''émettre des factures électroniques -- ne présumez donc pas que toute contrepartie équatorienne entre dans le champ d''application.', 'Le changement de la fenêtre de transmission de janvier 2026 étant récent, la plupart des entreprises ont encore un véritable travail de mise en œuvre devant elles : vérifier que leurs systèmes transmettent de nouveau immédiatement plutôt que de s''appuyer sur la fenêtre d''urgence désormais supprimée, et que leurs processus d''annulation reflètent l''échéance raccourcie.', 'L''Équateur appuie ses règles de facturation électronique sur un régime de sanctions réel et documenté, exprimé en Remuneración Básica Unificada (RBU) -- le salaire de base unifié de l''Équateur, confirmé à 482 USD pour 2026 -- qui augmente nettement selon la catégorie de contribuable, des grands contribuables jusqu''aux personnes non enregistrées.', 'Le SRI équatorien exige la transmission des factures électroniques quasi en temps réel depuis 2014, atteignant une couverture pratiquement universelle parmi les contribuables assujettis à la TVA fin 2022 (à l''exception de RIMPE Negocios Populares). Un délai de grâce temporaire de 4 jours ouvrables accordé pendant la crise d''urgence électrique de 2024 a été supprimé le 1er janvier 2026, rétablissant la règle en vigueur de transmission immédiate. Le modèle se décrit mieux comme un dédouanement : les émetteurs calculent eux-mêmes une clé d''autorisation de 49 chiffres, et la validation automatisée du SRI -- généralement achevée en quelques secondes -- est requise pour la validité légale.', '🇪🇨' FROM countries WHERE name_en = 'Ecuador';

