INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Jusqu''à 14 460 USD', 'Sanction pour non-transmission pour les grands contribuables (30 RBU)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.name_en = 'Ecuador' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format, clés et validation', '[["Format", "XML, conforme aux schémas XSD publiés par le SRI"], ["Clé d''autorisation", "Clé d''accès auto-calculée de 49 chiffres (clave de acceso) : date, type de document, RUC, environnement, établissement, point d''émission, numéro séquentiel, composante aléatoire, type d''émission et chiffre de contrôle"], ["Signature numérique", "Signature électronique avancée obligatoire (Firma Electrónica Avanzada / XAdES-BES)"], ["Validation du SRI", "Automatisée ; généralement achevée en quelques secondes et requise pour la validité légale"]]', 'Certaines sources fournisseurs décrivent une séquence plus stricte où le SRI approuve d''abord puis la facture est livrée ; d''autres décrivent une livraison immédiate avec autorisation en parallèle, la facture devenant « definitivo » une fois autorisée par le SRI. Il s''agit d''une ambiguïté réelle et non résolue dans les sources secondaires -- en pratique, la plupart des mises en œuvre traitent cela comme une séquence de dédouanement, la validation du SRI étant normalement quasi instantanée et requise avant qu''une facture ne soit légalement valide.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'RIDE, conservation et livraison', '[["RIDE", "Representación Impresa de Documento Electrónico -- une représentation imprimée portant un code-barres GS1-128, requise lorsque le destinataire ne peut pas ou ne veut pas accepter le XML directement"], ["Livraison", "Le XML est livré directement à l''acheteur, ou le RIDE lorsqu''une copie imprimée/visuelle est requise"], ["Conservation", "Minimum 7 ans, pour l''émetteur comme pour le destinataire"], ["Autorité compétente", "Servicio de Rentas Internas (SRI)"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Famille de documents', '[["Facturas", "Factures standard"], ["Comprobantes de retención", "Justificatifs de retenue à la source"], ["Guías de remisión", "Documents d''accompagnement des marchandises en transit"], ["Notas de crédito / débito", "Notes de crédit et notes de débit"], ["Liquidaciones de compra", "Liquidations d''achat"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'file_format' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de dédouanement auto-calculé', 'Une facture électronique équatorienne suit cette séquence -- l''émetteur effectue le calcul initial, mais c''est l''autorisation du SRI qui rend le document valide :', 'La validation automatisée du SRI est généralement achevée en quelques secondes -- considérez l''autorisation comme une étape requise et quasi immédiate de l''émission, non comme une formalité en arrière-plan.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador';
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'L''émetteur génère la facture XML et calcule lui-même sa clé d''accès de 49 chiffres' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'L''émetteur applique la signature électronique avancée obligatoire (XAdES-BES)' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le XML signé est soumis au SRI pour validation automatisée' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'Le SRI autorise le document -- généralement en quelques secondes -- et attribue le número de autorización' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT st.id, 'fr', 'La facture autorisée est livrée à l''acheteur, en XML ou sous forme de RIDE lorsqu''une copie imprimée est requise' FROM deep_dive_lifecycle_statuses_v2 st JOIN deep_dive_lifecycle_cards lc ON st.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.name_en = 'Ecuador' AND st.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui entre réellement dans le champ d''application', '[["Contribuables généraux assujettis à la TVA", "Dans le champ d''application, à la suite du déploiement progressif 2014-2022 ayant atteint une universalité effective"], ["RIMPE Emprendedores", "Dans le champ d''application (revenus jusqu''à 300 000 USD)"], ["RIMPE Negocios Populares", "EXEMPTÉS -- revenus jusqu''à 20 000 USD ; peuvent continuer à utiliser des notas de venta RISE papier"], ["Fournisseurs étrangers/non-résidents", "Entrent dans le champ d''application lors de leur enregistrement fiscal en Équateur"]]', 'Pratiquement universel en dehors de l''exception Negocios Populares -- ne présumez pas que littéralement toute contrepartie équatorienne pratique la facturation électronique.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Historique de la fenêtre de transmission', '[["2014-2018", "Immédiate, au moment de la transaction"], ["2018-2024", "Immédiate, ou jusqu''à 72 heures pour les émetteurs à fort volume"], ["Nov. 2024-déc. 2025", "Immédiate, ou jusqu''à 4 jours ouvrables -- allègement temporaire lié à l''urgence électrique"], ["À partir du 1er janv. 2026", "De nouveau immédiate -- le délai de 4 jours ouvrables a été supprimé"]]', 'Le changement de janvier 2026 met fin à un assouplissement temporaire accordé pendant l''urgence électrique de l''Équateur en 2024 -- il rétablit, plutôt qu''il n''introduit, une exigence de transmission quasi en temps réel applicable depuis 2014.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'scope_transmission' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 Les sanctions sont fixées en RBU et augmentent nettement selon la catégorie de contribuable', NULL, NULL, 'La résolution du SRI NAC-DGERCGC24-00000022 (6 juin 2024) fixe les sanctions en Remuneración Básica Unificada (RBU) -- le salaire de base unifié de l''Équateur, confirmé à 482 USD pour 2026 -- avec des montants distincts, plus élevés pour la non-transmission d''une facture que pour sa non-livraison, et un barème qui augmente nettement selon la catégorie, des grands contribuables jusqu''aux personnes non enregistrées. Voir le tableau des sanctions ci-dessous pour des montants représentatifs.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔒 Les factures consumidor final ne sont désormais plus annulables', NULL, NULL, 'À compter du 1er janvier 2026, les factures émises au « consumidor final » ne peuvent plus être annulées, en même temps qu''une échéance d''annulation raccourcie -- déplacée du 10 au 7 du mois suivant par la résolution NAC-DGERCGC25-00000017. Les entreprises qui annulaient ou corrigeaient habituellement les factures aux consommateurs finaux après coup doivent désormais adopter un processus différent.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ L''exception Negocios Populares ne signifie pas un risque nul', NULL, NULL, 'Même la plus petite catégorie de contribuables équatoriens n''est pas exempte de sanctions : RIMPE Negocios Populares reste exposé à une amende de 1 RBU (environ 482 USD) en cas de manquement à la livraison ou à la transmission, bien que cette catégorie soit exemptée de l''obligation de facturation électronique elle-même et autorisée à utiliser des notas de venta RISE papier.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.name_en = 'Ecuador' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Grands contribuables (grandes contribuyentes y grandes patrimonios) -- non-livraison / non-transmission', '9 640 USD / 14 460 USD (20 RBU / 30 RBU)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Ecuador' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Contribuables spéciaux (contribuyentes especiales) -- non-livraison / non-transmission', '4 820 USD / 7 230 USD (10 RBU / 15 RBU)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Ecuador' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Sociétés tenues de tenir une comptabilité -- non-livraison / non-transmission', '3 374 USD / 4 820 USD (7 RBU / 10 RBU)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Ecuador' AND pr.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'RIMPE Negocios Populares -- non-livraison / non-transmission', '482 USD / 482 USD (1 RBU / 1 RBU)', '—' FROM deep_dive_penalty_rows pr JOIN countries c ON pr.country_id = c.id WHERE c.name_en = 'Ecuador' AND pr.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez quelle catégorie de contribuable s''applique à votre entreprise', 'Le champ d''application comme l''exposition aux sanctions dépendent du fait que vous soyez un grand contribuable, un contribuable spécial, une société générale, ou releviez de RIMPE Emprendedores ou Negocios Populares -- confirmez votre catégorie auprès du SRI ou d''un conseiller local avant de vous fier à un chiffre générique.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre logiciel de facturation génère correctement la clé d''accès de 49 chiffres et applique la signature XAdES-BES', 'Une clé d''accès mal formée ou l''absence de signature électronique avancée entraînera le rejet pur et simple de la facture par le SRI -- vérifiez les deux avant de mettre en production tout nouveau système.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Intégrez une vérification de l''autorisation du SRI en temps réel dans votre processus d''émission', 'Ne considérez pas une clé d''accès auto-calculée seule comme une facture valide -- c''est l''autorisation du SRI, normalement reçue en quelques secondes, qui rend réellement le document légalement valide.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Mettez à jour vos systèmes pour une transmission immédiate', 'La fenêtre d''urgence de 4 jours ouvrables accordée en novembre 2024 ne s''applique plus depuis le 1er janvier 2026 -- vérifiez que votre chaîne de facturation transmet immédiatement au SRI, et non selon le calendrier différé désormais supprimé.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Adaptez les processus d''annulation de factures pour les documents consumidor final', 'Les factures consumidor final sont devenues non annulables à compter du 1er janvier 2026, et l''échéance générale d''annulation est passée du 10 au 7 du mois suivant -- adaptez vos processus en conséquence.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Conservez les copies XML et RIDE pendant au moins 7 ans', 'L''émetteur comme le destinataire doivent conserver les documents électroniques pendant un minimum de 7 ans -- intégrez cette exigence à votre politique de gestion documentaire, tant pour les factures émises que reçues.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.name_en = 'Ecuador' AND sp.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'SRI — Facturación Electrónica (portail de la facturation électronique)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Ecuador' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Servicio de Rentas Internas (SRI) — site général' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.name_en = 'Ecuador' AND pt.sort_order = 1;
